import { BaseError } from './base';

type TokenSwapErrorParams = {
  message: string;
  originalError?: unknown;
};

export class TokenSwapError extends BaseError {
  constructor({ message, originalError }: TokenSwapErrorParams) {
    const cause =
      originalError && originalError instanceof Error ? originalError : null;
    super({
      cause,
      code: 'token_swap_error',
      docsUrl: null,
      name: 'TokenSwapError',
      shortMessage: message,
    });
  }
}
