import { getDefaultClient } from '../../../../client/defaultClient';
import { InvalidParamError } from '../../../../errors/InvalidParamError';
import { assertDefined } from '../../../../utils/assertDefined';
import type { CheckoutTransaction } from '../../checkout.types';
import { getCheckouts } from '../../getCheckouts';

export type RequiresConversionParams = {
  transaction: CheckoutTransaction;
};

/**
 * Determines whether a token conversion (swap/bridge) is required for a checkout transaction.
 *
 * Returns `true` when the from token does not match any settlement token defined in
 * the checkout's settlement config for the given chain — meaning the asset must be
 * converted before it can settle.
 * Returns `false` when the from token already matches a settlement token, so no
 * conversion is needed.
 *
 * @param params - The from token details and the checkout's settlement config.
 * @param [client] - The Dynamic client instance. Only required when using multiple Dynamic clients.
 * @returns Whether a token conversion is required
 * @instrumented
 */
export const requiresConversion = async (
  { transaction }: RequiresConversionParams,
  client = getDefaultClient()
): Promise<boolean> => {
  if (
    !transaction.fromChainId ||
    !transaction.fromChainName ||
    !transaction.fromToken
  ) {
    throw new InvalidParamError(
      'Transaction is missing source information. Make sure that attachCheckoutTransactionSource has been called before calling this function.'
    );
  }

  const allCheckouts = await getCheckouts(client);

  const checkout = allCheckouts.find(
    (checkout) => checkout.id === transaction.checkoutId
  );

  assertDefined(
    checkout,
    'Could not find checkout associated with transaction.'
  );

  return !checkout.settlementConfig.settlements.some(
    (settlement) =>
      settlement.chainName === transaction.fromChainName &&
      settlement.chainId === transaction.fromChainId &&
      settlement.tokenAddress === transaction.fromToken
  );
};
